insert into reviews (user_id, court_id, booking_id, rating, comment, display_status, created_at, updated_at) values
('00000000-0000-0000-0000-000000000021','30000000-0000-0000-0000-000000000003','41000000-0000-0000-0000-000000000001',5,'Sân cầu lông sạch, ánh sáng đều và đặt lịch rất nhanh. Nhóm mình vào chơi đúng giờ, không phải chờ xác nhận lâu.','VISIBLE','2026-05-20 20:45:00+07','2026-05-20 20:45:00+07'),
('00000000-0000-0000-0000-000000000022','30000000-0000-0000-0000-000000000004','41000000-0000-0000-0000-000000000002',5,'Sân pickleball mới, vạch sân rõ, nhân viên hỗ trợ đổi khung giờ rất dễ thương. Sẽ quay lại vào cuối tuần.','VISIBLE','2026-05-21 21:30:00+07','2026-05-21 21:30:00+07'),
('00000000-0000-0000-0000-000000000023','30000000-0000-0000-0000-000000000005','41000000-0000-0000-0000-000000000003',4,'Không gian chơi ổn, có mái che nên buổi chiều đỡ nắng. Khu gửi xe hơi đông nhưng vẫn chấp nhận được.','VISIBLE','2026-05-22 19:45:00+07','2026-05-22 19:45:00+07'),
('00000000-0000-0000-0000-000000000024','30000000-0000-0000-0000-000000000006','41000000-0000-0000-0000-000000000004',5,'Mặt cỏ mềm, đèn sáng và vị trí dễ tìm. Đội mình đặt sân tối nhưng check-in vẫn rất gọn.','VISIBLE','2026-05-23 20:35:00+07','2026-05-23 20:35:00+07'),
('00000000-0000-0000-0000-000000000025','30000000-0000-0000-0000-000000000007','41000000-0000-0000-0000-000000000005',4,'Sân tennis yên tĩnh, phù hợp tập buổi sáng. Nếu có thêm nước uống lạnh gần sân thì sẽ tiện hơn.','VISIBLE','2026-05-24 09:00:00+07','2026-05-24 09:00:00+07'),
('00000000-0000-0000-0000-000000000026','30000000-0000-0000-0000-000000000008','41000000-0000-0000-0000-000000000006',4,'Sân bóng chuyền thoáng, gần biển nên chơi chiều rất dễ chịu. Giá hợp lý cho nhóm sinh viên.','VISIBLE','2026-05-25 18:40:00+07','2026-05-25 18:40:00+07'),
('00000000-0000-0000-0000-000000000027','30000000-0000-0000-0000-000000000009','41000000-0000-0000-0000-000000000007',5,'Nhà thi đấu rộng, nhiều sân và lịch trống hiển thị đúng. Đặt xong có thông báo rõ ràng.','VISIBLE','2026-05-26 21:40:00+07','2026-05-26 21:40:00+07'),
('00000000-0000-0000-0000-000000000028','30000000-0000-0000-0000-000000000010','41000000-0000-0000-0000-000000000008',4,'Sân pickleball phù hợp chơi gia đình, có chỗ nghỉ cạnh sân. Cuối tuần hơi đông nên nên đặt sớm.','VISIBLE','2026-05-27 20:35:00+07','2026-05-27 20:35:00+07'),
('00000000-0000-0000-0000-000000000029','30000000-0000-0000-0000-000000000011','41000000-0000-0000-0000-000000000009',5,'Cụm sân bóng rất chuyên nghiệp, mặt sân đều và khu thay đồ sạch. Rất đáng để tổ chức giao hữu.','VISIBLE','2026-05-28 22:25:00+07','2026-05-28 22:25:00+07'),
('00000000-0000-0000-0000-000000000030','30000000-0000-0000-0000-000000000012','41000000-0000-0000-0000-000000000010',5,'Nhiều sân cầu lông, trần cao và đèn không bị chói. Khung sáng giá tốt, đặt nhanh trên web.','VISIBLE','2026-05-29 09:45:00+07','2026-05-29 09:45:00+07'),
('00000000-0000-0000-0000-000000000031','30000000-0000-0000-0000-000000000013','41000000-0000-0000-0000-000000000011',4,'Mặt sân tennis còn tốt, có huấn luyện viên theo giờ. Khu chờ hơi nhỏ nếu đi đông người.','VISIBLE','2026-05-30 20:50:00+07','2026-05-30 20:50:00+07'),
('00000000-0000-0000-0000-000000000032','30000000-0000-0000-0000-000000000014','41000000-0000-0000-0000-000000000012',5,'Sân bóng rổ trong nhà đẹp, bảng rổ chắc và sàn bám tốt. Cảm giác rất đáng tin cậy.','VISIBLE','2026-05-31 21:35:00+07','2026-05-31 21:35:00+07'),
('00000000-0000-0000-0000-000000000021','30000000-0000-0000-0000-000000000015','41000000-0000-0000-0000-000000000013',4,'Sân bóng chuyền gần biển, gió mát và dễ tìm. Nên bổ sung thêm bảng chỉ dẫn vào khu sân.','VISIBLE','2026-06-01 19:55:00+07','2026-06-01 19:55:00+07'),
('00000000-0000-0000-0000-000000000022','30000000-0000-0000-0000-000000000016','41000000-0000-0000-0000-000000000014',5,'Pickleball Riverside có mặt sân mới, khu vực quanh sân sáng và thoáng. Rất hợp chơi sau giờ làm.','VISIBLE','2026-06-02 20:45:00+07','2026-06-02 20:45:00+07'),
('00000000-0000-0000-0000-000000000023','30000000-0000-0000-0000-000000000017','41000000-0000-0000-0000-000000000015',4,'Sân bóng trung tâm Cần Thơ, giá hợp lý và nhân viên xác nhận lịch nhanh. Buổi tối khá đông.','VISIBLE','2026-06-03 22:35:00+07','2026-06-03 22:35:00+07'),
('00000000-0000-0000-0000-000000000024','30000000-0000-0000-0000-000000000018','41000000-0000-0000-0000-000000000016',5,'Sân cầu lông mở sớm, phù hợp tập trước giờ đi làm. Thảm êm và nhà vệ sinh sạch.','VISIBLE','2026-06-04 08:50:00+07','2026-06-04 08:50:00+07'),
('00000000-0000-0000-0000-000000000025','30000000-0000-0000-0000-000000000019','41000000-0000-0000-0000-000000000017',4,'Sân tennis yên tĩnh, dễ đặt lịch. Mình thích phần hiển thị giá rõ trước khi đặt.','VISIBLE','2026-06-05 20:55:00+07','2026-06-05 20:55:00+07'),
('00000000-0000-0000-0000-000000000026','30000000-0000-0000-0000-000000000020','41000000-0000-0000-0000-000000000018',5,'Vị trí gần trung tâm, sân pickleball sạch và có nhiều khung giờ tối. Đặt nhanh hơn gọi điện nhiều.','VISIBLE','2026-06-06 21:30:00+07','2026-06-06 21:30:00+07'),
('00000000-0000-0000-0000-000000000027','30000000-0000-0000-0000-000000000001','41000000-0000-0000-0000-000000000019',5,'Sân bóng Sala vẫn là lựa chọn tốt cho đội mình, mặt sân êm và khu gửi xe rộng.','VISIBLE','2026-06-07 20:55:00+07','2026-06-07 20:55:00+07'),
('00000000-0000-0000-0000-000000000028','30000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000020',4,'Sân tennis sạch, lịch sáng ít đông và giá ổn. Phần đặt lịch trên web dễ dùng.','VISIBLE','2026-06-08 09:10:00+07','2026-06-08 09:10:00+07')
